import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import {
  motion,
  AnimatePresence,
  useReducedMotion,
  type Transition,
  type Variants,
} from "framer-motion";
import { cn } from "@/lib/utils";

export type PageTransitionVariant =
  | "push-pull"
  | "fade"
  | "wipe"
  | "scale"
  | "veil"
  | "iris";

export interface PageTransitionViewportProps {
  children: React.ReactNode;
  /**
   * Unique key for the current "page". When this changes, the previous
   * subtree is held in the DOM long enough to play its exit animation.
   * In Next.js App Router, pass `usePathname()`.
   */
  routeKey: string;
  /** Visual style of the route transition. */
  variant?: PageTransitionVariant;
  /** Override the spring that drives every animated property. */
  transition?: Transition;
  /** Show a thin chili progress bar at the top during every transition. */
  showProgressBar?: boolean;
  className?: string;
}

const DEFAULT_TRANSITION: Transition = {
  type: "spring",
  stiffness: 280,
  damping: 34,
  mass: 0.65,
};

const VARIANTS: Record<PageTransitionVariant, Variants> = {
  "push-pull": {
    initial: { opacity: 0, y: 32, scale: 0.985, filter: "blur(8px)" },
    enter: { opacity: 1, y: 0, scale: 1, filter: "blur(0px)" },
    exit: { opacity: 0, y: -16, scale: 0.972, filter: "blur(6px)" },
  },
  fade: {
    initial: { opacity: 0 },
    enter: { opacity: 1 },
    exit: { opacity: 0 },
  },
  wipe: {
    initial: { clipPath: "inset(0% 0% 100% 0%)", opacity: 0 },
    enter: { clipPath: "inset(0% 0% 0% 0%)", opacity: 1 },
    exit: { clipPath: "inset(100% 0% 0% 0%)", opacity: 0 },
  },
  scale: {
    initial: { opacity: 0, scale: 0.94, filter: "blur(4px)" },
    enter: { opacity: 1, scale: 1, filter: "blur(0px)" },
    exit: { opacity: 0, scale: 1.04, filter: "blur(4px)" },
  },
  // "Veil" — incoming page rises behind a thin chili bar that sweeps off-screen.
  veil: {
    initial: { opacity: 0, y: 24, filter: "blur(10px)" },
    enter: { opacity: 1, y: 0, filter: "blur(0px)" },
    exit: { opacity: 0, y: -8, filter: "blur(6px)" },
  },
  // "Iris" — circular clip-path opens from the center.
  iris: {
    initial: { clipPath: "circle(0% at 50% 50%)", opacity: 0.85 },
    enter: { clipPath: "circle(140% at 50% 50%)", opacity: 1 },
    exit: { clipPath: "circle(0% at 50% 50%)", opacity: 0 },
  },
};

/**
 * PageTransitionViewport
 *
 * Drop this around your `{children}` in a Next.js App Router layout to make
 * route changes feel like a native iOS app. Pass `usePathname()` as
 * `routeKey` so the outgoing page is held in the DOM long enough to play
 * its exit animation before unmount.
 *
 * Animation contract: only `transform`, `opacity`, `filter`, `clip-path`.
 *
 * Bonus: a thin top progress bar (opt-in via `showProgressBar`) fires every
 * time the route changes, giving users immediate feedback that something
 * is loading — even when the transition itself is sub-200ms.
 */
export function PageTransitionViewport({
  children,
  routeKey,
  variant = "push-pull",
  transition = DEFAULT_TRANSITION,
  showProgressBar = false,
  className,
}: PageTransitionViewportProps) {
  const reduce = useReducedMotion();
  const variants = reduce
    ? {
        initial: { opacity: 1 },
        enter: { opacity: 1 },
        exit: { opacity: 1 },
      }
    : VARIANTS[variant];

  return (
    <div className={cn("relative isolate w-full", className)}>
      {showProgressBar && !reduce && <RouteProgressBar routeKey={routeKey} />}

      {/* Veil sweep — only for the `veil` variant. */}
      {variant === "veil" && !reduce && (
        <AnimatePresence initial={false}>
          <motion.span
            key={`veil-${routeKey}`}
            aria-hidden
            className="pointer-events-none absolute inset-x-0 top-0 z-40 h-full origin-bottom bg-chili-500"
            initial={{ scaleY: 1 }}
            animate={{ scaleY: 0 }}
            transition={{ duration: 0.55, ease: [0.83, 0, 0.17, 1] }}
            style={{ willChange: "transform" }}
          />
        </AnimatePresence>
      )}

      <AnimatePresence mode="wait" initial={false}>
        <motion.div
          key={routeKey}
          variants={variants}
          initial="initial"
          animate="enter"
          exit="exit"
          transition={transition}
          style={{ willChange: "transform, opacity, filter" }}
          className="relative w-full"
        >
          {children}
        </motion.div>
      </AnimatePresence>
    </div>
  );
}

/* ─────────────────────────── Top progress bar ───────────────────────── */

function RouteProgressBar({ routeKey }: { routeKey: string }) {
  return (
    <AnimatePresence initial={false} mode="wait">
      <motion.div
        key={`bar-${routeKey}`}
        aria-hidden
        className="pointer-events-none absolute inset-x-0 top-0 z-50 h-[2px] origin-left bg-gradient-to-r from-chili-500 via-chili-400 to-chili-500"
        initial={{ scaleX: 0, opacity: 1 }}
        animate={{ scaleX: 1, opacity: 1 }}
        exit={{ opacity: 0 }}
        transition={{
          scaleX: { duration: 0.65, ease: [0.22, 1, 0.36, 1] },
          opacity: { duration: 0.25, delay: 0.4 },
        }}
        style={{ willChange: "transform, opacity" }}
      />
    </AnimatePresence>
  );
}
